<?php

declare(strict_types=1);

namespace Database\Seeders\Translations;

use InvalidArgumentException;

/**
 * Frontend strings (it, en, de, fr) of the Privacy & Data Governance Suite (Mod 096, GDPR / nLPD): dashboard, RoPA, DSAR,
 * erasure, data breach assistant, consent ledger and retention. Every key carries its four texts in the order
 * [it, en, de, fr], so a key can never exist in one language only. Merged by FrontendTranslationSeeder::dictionary().
 *
 * Texts use double quotes and contain no dollar sign or double quote, so they stay literal.
 */
final class PrivacyGovernanceFrontendTranslations
{
    private const LOCALES = ['it' => 0, 'en' => 1, 'de' => 2, 'fr' => 3];

    /**
     * @return array<string, string>
     */
    public static function all(string $locale): array
    {
        if (! isset(self::LOCALES[$locale])) {
            throw new InvalidArgumentException("Unsupported locale [{$locale}].");
        }

        $index = self::LOCALES[$locale];
        $dictionary = [];

        foreach (self::entries() as $key => $texts) {
            $dictionary[$key] = $texts[$index];
        }

        return $dictionary;
    }

